# Builds the app icon from the axolotl's head.
#   python tools/gen_icon.py
# Writes assets/icon.svg, then (via `cargo run --example rasterize` + Pillow)
# assets/icon.png (512), assets/icon.ico (16..256) and assets/icon.icns.
import os, subprocess, sys

sys.path.insert(0, os.path.dirname(__file__))
import gen_axolotl as ax  # noqa: E402

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
ASSETS = os.path.join(ROOT, "assets")
TILE = "#fff1ea"

svg = f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="256" height="256">
  <!-- pomolotl app icon (generated by tools/gen_icon.py) -->
  <rect x="8" y="8" width="240" height="240" rx="58" fill="{TILE}" stroke="{ax.OUT}" stroke-width="6"/>
  <g transform="translate(128 134) scale(1.62)">
    {ax.head("open", "smile")}
  </g>
</svg>
'''

def main():
    from PIL import Image
    path = os.path.join(ASSETS, "icon.svg")
    with open(path, "w", encoding="utf8", newline="\n") as f:
        f.write(svg)
    big = os.path.join(ASSETS, "icon-1024.png")
    subprocess.run(["cargo", "run", "-q", "--example", "rasterize", "--", path, "1024", big],
                   check=True, cwd=ROOT)
    img = Image.open(big).convert("RGBA")
    img.resize((512, 512), Image.LANCZOS).save(os.path.join(ASSETS, "icon.png"))
    img.save(os.path.join(ASSETS, "icon.ico"),
             sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)])
    img.save(os.path.join(ASSETS, "icon.icns"))
    os.remove(big)
    print("ok")

if __name__ == "__main__":
    main()
